-- 0048 — VERIFIED APPLY (generated by scripts/release/build-verified.mjs; do not edit by hand).
--
-- Applies supabase/migrations/0048_upload_limits_and_verification.sql exactly as written, inside one transaction that
-- first fingerprints all existing data (every row of every table in public, plus which files are
-- in storage and which users exist) and checks it again afterwards. If anything existing changed —
-- other than the new column(s) this migration adds — it stops with an error and NOTHING is applied.
-- On success the last result shows what was checked.
--
-- Run it in the Supabase SQL editor (paste the whole file, Run) or: psql "$DATABASE_URL" -f this-file

begin isolation level repeatable read;
set local lock_timeout = '10s';     -- don't queue behind a long query; just fail and retry later
set local statement_timeout = '5min';
lock table storage.buckets in share row exclusive mode;  -- writes wait a few seconds; reads continue

create temp table if not exists _release_check (phase text not null, tbl text not null, n bigint not null, h text not null, primary key (phase, tbl)) on commit preserve rows;
truncate pg_temp._release_check;

do $fp$
declare
  t record;
  drop_keys jsonb := '{}'::jsonb;
begin
  for t in
    select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind in ('r', 'p')
       and ('before' = 'before' or exists (select 1 from pg_temp._release_check b where b.phase = 'before' and b.tbl = c.relname))
     order by 1
  loop
    execute format(
      'insert into pg_temp._release_check select %L, %L, count(*), md5(coalesce(string_agg(x, E''\n'' order by x), '''')) from (select (to_jsonb(r) - %L::text[])::text as x from public.%I r) s',
      'before', t.relname, coalesce((select array_agg(v) from jsonb_array_elements_text(drop_keys -> t.relname) v), '{}'::text[]), t.relname);
  end loop;
  insert into pg_temp._release_check
    select 'before', 'storage.objects', count(*), md5(coalesce(string_agg(bucket_id || '/' || name || '#' || coalesce(metadata ->> 'size', ''), E'\n' order by bucket_id, name), '')) from storage.objects;
  insert into pg_temp._release_check
    select 'before', 'auth.users', count(*), md5(coalesce(string_agg(id::text || ' ' || coalesce(email, ''), E'\n' order by id), '')) from auth.users;
end
$fp$;

-- ===================== migration 0048_upload_limits_and_verification (verbatim) =====================
-- 0048: upload limits, and client uploads checked on the server before they count.
--
-- 1. Both storage buckets accept files up to 25 MB, and only these content types (the app stores
--    every file with the type its extension implies — src/services/uploads/uploadCheck.ts):
--    PDF, JPEG, PNG, WebP, HEIC/HEIF, Word (.docx/.doc), Excel (.xlsx/.xls), CSV, plain text.
--    Storage enforces both, whatever the browser sends.
--
-- 2. upload_verifications: files whose real contents the server checked (api/verify-upload reads
--    the first 4 KB with the service key and compares them with the extension; a mismatch is
--    deleted). Written only by that route (service role); nobody else reads or writes it.
--
-- 3. The switch: app_settings 'require_upload_verification'. While false (the default), nothing
--    changes. Once true, a client's upload (a document request or an intake submission) can only be
--    recorded if it was verified — enforced here by a trigger on the tables the upload functions
--    write, so no client and no RPC can skip it. Turn it on only after api/verify-upload is deployed
--    and configured (see SUPABASE_SETUP.md):
--      update public.app_settings set value = 'true' where key = 'require_upload_verification';
--
-- Additive and re-runnable. Existing files and rows are untouched.

-- 1. Bucket limits --------------------------------------------------------------------------
update storage.buckets
   set file_size_limit = 26214400,
       allowed_mime_types = array[
         'application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif',
         'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword',
         'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-excel',
         'text/csv', 'text/plain'
       ]
 where id in ('submission-documents', 'intake-uploads');

-- 2. Verified uploads -------------------------------------------------------------------------
create table if not exists public.upload_verifications (
  bucket_id text not null,
  object_name text not null,
  kind text not null check (kind in ('pdf', 'jpeg', 'png', 'webp', 'heic', 'zip', 'ole', 'text')),
  size_bytes bigint,
  verified_at timestamptz not null default now(),
  primary key (bucket_id, object_name)
);
alter table public.upload_verifications enable row level security;
revoke all on public.upload_verifications from public, anon, authenticated;

-- 3. The switch and its enforcement ----------------------------------------------------------
create table if not exists public.app_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.app_settings enable row level security;
revoke all on public.app_settings from public, anon, authenticated;
insert into public.app_settings (key, value) values ('require_upload_verification', 'false') on conflict (key) do nothing;

do $$ begin
  grant select, insert, update on public.upload_verifications to service_role;
  grant select on public.app_settings to service_role;
exception when undefined_object then null;
end $$;

create or replace function public.require_verified_upload() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if coalesce((select (s.value)::text = 'true' from public.app_settings s where s.key = 'require_upload_verification'), false)
     and new.storage_path is not null
     and not exists (select 1 from public.upload_verifications v where v.bucket_id = 'intake-uploads' and v.object_name = new.storage_path) then
    raise exception 'This file hasn''t been checked yet — upload it again.' using errcode = '22023';
  end if;
  return new;
end;
$$;
revoke all on function public.require_verified_upload() from public, anon, authenticated;

drop trigger if exists document_request_files_verified_upload on public.document_request_files;
create trigger document_request_files_verified_upload
  before insert or update of storage_path on public.document_request_files
  for each row execute function public.require_verified_upload();

drop trigger if exists intake_documents_verified_upload on public.intake_documents;
create trigger intake_documents_verified_upload
  before insert or update of storage_path on public.intake_documents
  for each row execute function public.require_verified_upload();

notify pgrst, 'reload schema';
-- ===================== end of migration =====================


do $fp$
declare
  t record;
  drop_keys jsonb := '{}'::jsonb;
begin
  for t in
    select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind in ('r', 'p')
       and ('after' = 'before' or exists (select 1 from pg_temp._release_check b where b.phase = 'before' and b.tbl = c.relname))
     order by 1
  loop
    execute format(
      'insert into pg_temp._release_check select %L, %L, count(*), md5(coalesce(string_agg(x, E''\n'' order by x), '''')) from (select (to_jsonb(r) - %L::text[])::text as x from public.%I r) s',
      'after', t.relname, coalesce((select array_agg(v) from jsonb_array_elements_text(drop_keys -> t.relname) v), '{}'::text[]), t.relname);
  end loop;
  insert into pg_temp._release_check
    select 'after', 'storage.objects', count(*), md5(coalesce(string_agg(bucket_id || '/' || name || '#' || coalesce(metadata ->> 'size', ''), E'\n' order by bucket_id, name), '')) from storage.objects;
  insert into pg_temp._release_check
    select 'after', 'auth.users', count(*), md5(coalesce(string_agg(id::text || ' ' || coalesce(email, ''), E'\n' order by id), '')) from auth.users;
end
$fp$;

do $check$
declare
  changed text;
begin
  select string_agg(b.tbl || ' (' || b.n || ' → ' || coalesce(a.n::text, 'missing') || ' rows)', ', ' order by b.tbl) into changed
    from pg_temp._release_check b
    left join pg_temp._release_check a on a.phase = 'after' and a.tbl = b.tbl
   where b.phase = 'before' and (a.tbl is null or a.n <> b.n or a.h <> b.h);
  if changed is not null then
    raise exception 'STOPPED — existing data would change in: %. Nothing from 0048 was applied.', changed;
  end if;
  if not (select coalesce((select value::text = 'false' from public.app_settings where key = 'require_upload_verification'), false)) then raise exception 'STOPPED — %. Nothing from 0048 was applied.', 'Upload enforcement must start switched off.'; end if;
end
$check$;

commit;

-- What was checked (all unchanged):
select '0048 applied and verified' as result,
       (select n from pg_temp._release_check where phase = 'before' and tbl = 'submissions') as accounts,
       (select n from pg_temp._release_check where phase = 'before' and tbl = 'documents') as documents,
       (select n from pg_temp._release_check where phase = 'before' and tbl = 'document_requests') as client_requests,
       (select coalesce(sum(case when jsonb_typeof(missing_items) = 'array' then jsonb_array_length(missing_items) end), 0) from public.submissions) as checklist_items,
       (select coalesce(sum(case when jsonb_typeof(follow_ups) = 'array' then jsonb_array_length(follow_ups) end), 0) from public.submissions) as account_follow_ups,
       (select count(*) from public.document_requests where next_follow_up is not null) as request_follow_ups,
       (select n from pg_temp._release_check where phase = 'before' and tbl = 'activity_events') as activity_entries,
       (select n from pg_temp._release_check where phase = 'before' and tbl = 'storage.objects') as stored_files,
       (select count(*) from pg_temp._release_check where phase = 'before') as tables_checked;
